-- 00013_drill_library.sql
-- Basketball drill library: every drill with setup, steps, coaching cues and
-- common mistakes, filterable by skill, level and number of players.
-- Read-only for players; the drill list is added at the end. Safe to re-run.

CREATE TABLE IF NOT EXISTS public.drills (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text UNIQUE NOT NULL,
  name text NOT NULL,
  skill text NOT NULL CHECK (skill IN (
    'shooting', 'ball_handling', 'finishing', 'footwork', 'passing',
    'defense', 'rebounding', 'post_play', 'conditioning', 'iq'
  )),
  sub_skill text NOT NULL,
  level text NOT NULL CHECK (level IN ('beginner', 'intermediate', 'advanced')),
  players text NOT NULL CHECK (players IN ('solo', 'partner', 'team')),
  equipment text[] NOT NULL DEFAULT '{}',
  duration_minutes integer NOT NULL CHECK (duration_minutes BETWEEN 1 AND 120),
  reps text NOT NULL,
  setup text NOT NULL,
  instructions text[] NOT NULL,
  coaching_cues text[] NOT NULL,
  common_mistakes text[] NOT NULL,
  tracks_makes boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_drills_skill_level ON public.drills(skill, level);

ALTER TABLE public.drills ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Players can view drills" ON public.drills;
CREATE POLICY "Players can view drills" ON public.drills FOR SELECT TO authenticated USING (true);

-- This project does not auto-grant new tables to the API roles (see 00008)
GRANT SELECT ON public.drills TO authenticated;
GRANT ALL ON public.drills TO service_role;
REVOKE ALL ON public.drills FROM anon;

-- =============================================================================
-- DRILLS
-- =============================================================================
-- HoopIQ drill library seed (150 drills). Safe to re-run.
ON CONFLICT (slug) DO NOTHING;
