INSERT INTO public.drills (slug, name, skill, sub_skill, level, players, equipment, duration_minutes, reps, setup, instructions, coaching_cues, common_mistakes, tracks_makes) VALUES
  ('form-shooting-one-hand', 'One-Hand Form Shooting', 'shooting', 'form', 'beginner', 'solo', ARRAY['ball', 'hoop'], 8, '5 spots x 10 makes', 'Start 3 feet from the rim, directly in front, then work to both blocks and both short elbows.', ARRAY['Hold the ball in your shooting hand only, with the guide hand behind your back', 'Set your elbow under the ball and load your wrist back', 'Rise with your legs and extend up, finishing with a high follow-through', 'Hold your follow-through until the ball hits the floor', 'Take one step back only after 10 makes at the current spot'], ARRAY['Elbow under the ball', 'Reach into the cookie jar', 'Legs start the shot'], ARRAY['Letting the elbow flare out to the side', 'Pushing the ball flat instead of shooting up and over the rim'], true),
  ('form-shooting-ladder', 'Form Shooting Ladder', 'shooting', 'form', 'beginner', 'solo', ARRAY['ball', 'hoop'], 10, '3 distances x 10 makes', 'Line up straight in front of the rim at 3 feet, then 6 feet, then the free throw line.', ARRAY['Start at 3 feet with two-hand form, guide hand on the side of the ball', 'Make 10 shots, then move back to 6 feet', 'Make 10 more, then finish with 10 at the free throw line', 'If you miss 3 in a row, move back one distance'], ARRAY['Same shot every distance', 'Guide hand stays quiet', 'Swish, don''t just make'], ARRAY['Changing your form as the distance grows', 'Rushing the next shot before you reset your feet'], true),
  ('lie-down-form-shots', 'Lie-Down Form Shots', 'shooting', 'form', 'beginner', 'solo', ARRAY['ball'], 4, '3 x 25 shots', 'Lie on your back on the floor or a bed with the ball in your shooting hand.', ARRAY['Hold the ball above your face with your elbow pointed at the ceiling', 'Shoot the ball straight up 3 to 6 feet with backspin', 'Catch it and reset your hand before each rep', 'Keep the ball rotating straight so it lands back in your hand'], ARRAY['Elbow to the ceiling', 'Snap and wave goodbye', 'Straight backspin'], ARRAY['Letting the ball drift sideways from a twisted wrist', 'Using the guide hand to push the ball'], false),
  ('wall-target-shooting', 'Wall Target Shooting', 'shooting', 'form', 'beginner', 'solo', ARRAY['ball', 'wall'], 5, '3 x 20 shots', 'Stand 4 to 6 feet from a wall and pick a spot about 12 feet high as your target.', ARRAY['Get into your shooting stance with feet shoulder-width apart', 'Shoot at the target with a full follow-through and high arc', 'Catch the rebound and reset your feet each time', 'Check that the ball comes straight back with clean backspin'], ARRAY['Aim high, finish higher', 'Same release every rep', 'Toes, knees, and elbow line up'], ARRAY['Shooting on a flat line at the wall', 'Skipping the follow-through because there is no rim'], false),
  ('free-throw-routine-builder', 'Free Throw Routine Builder', 'shooting', 'free_throws', 'beginner', 'solo', ARRAY['ball', 'hoop'], 10, '5 sets of 10 free throws', 'Stand at the free throw line with your shooting foot lined up on the middle of the rim.', ARRAY['Build a routine you repeat every time, such as three dribbles and a deep breath', 'Pick a target on the rim and lock your eyes on it', 'Shoot and hold your follow-through until the ball lands', 'Record your makes out of 10 for each set'], ARRAY['Same routine every shot', 'Breathe out before you shoot', 'Hold the finish'], ARRAY['Changing your routine after a miss', 'Shooting with just your arms and no leg bend'], true),
  ('ten-in-a-row-free-throws', '10 in a Row Free Throws', 'shooting', 'free_throws', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 10, 'Make 10 in a row', 'Stand at the free throw line with a ball and your normal routine ready.', ARRAY['Shoot free throws with your full routine', 'Count consecutive makes', 'If you miss, the count resets to zero', 'Finish when you hit 10 in a row or reach 10 minutes'], ARRAY['One shot at a time', 'Trust the routine', 'Relax your shoulders'], ARRAY['Speeding up as the streak grows', 'Skipping the routine when the count resets'], true),
  ('tired-legs-free-throws', 'Tired Legs Free Throws', 'shooting', 'free_throws', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 10, '5 rounds x 2 free throws', 'Start on the baseline with the ball, facing the far end of the court.', ARRAY['Sprint from the baseline to half court and back', 'Walk to the free throw line and shoot 2 with your full routine', 'Record your makes and rest 20 seconds', 'Repeat for 5 rounds'], ARRAY['Slow your breathing first', 'Legs under you', 'Routine beats fatigue'], ARRAY['Rushing the shot while still out of breath', 'Losing your base and shooting short'], true),
  ('free-throw-pressure-ladder', 'Free Throw Pressure Ladder', 'shooting', 'free_throws', 'advanced', 'solo', ARRAY['ball', 'hoop'], 12, 'Complete the ladder: 1, 2, 3, 4, then 5 in a row', 'Stand at the free throw line with a ball and room to sprint the length of the court.', ARRAY['Make 1 free throw, then 2 in a row, then 3, 4, and 5 in a row', 'Any miss sends you back to the start of that rung', 'After every miss, sprint baseline to baseline before shooting again', 'Finish the full ladder to complete the drill'], ARRAY['Treat every shot like game point', 'Same routine on every rung', 'Win the next shot'], ARRAY['Changing your routine when you reach the last rung', 'Shooting before your breathing settles after a sprint'], true),
  ('spin-out-catch-and-shoot', 'Spin-Out Catch and Shoot', 'shooting', 'catch_and_shoot', 'beginner', 'solo', ARRAY['ball', 'hoop'], 8, '5 spots x 5 makes', 'Start at any spot 12 to 15 feet from the rim, holding the ball.', ARRAY['Spin the ball out in front of you with backspin so it bounces back to you', 'Step into the catch with your inside foot and your hands ready', 'Catch in your shot pocket and rise into the shot', 'Move to the next spot after 5 makes'], ARRAY['Hands ready before the catch', 'Feet set on the catch', 'Shot pocket every time'], ARRAY['Catching with straight legs and having to dip', 'Fading away instead of landing where you took off'], true),
  ('five-spot-midrange', '5-Spot Midrange', 'shooting', 'catch_and_shoot', 'beginner', 'solo', ARRAY['ball', 'hoop'], 10, '5 spots x 10 shots', 'Mark 5 spots about 15 feet out: both baselines, both wings, and the top of the key.', ARRAY['Shoot 10 shots from the first spot, rebounding your own ball', 'Dribble back out and square up before every shot', 'Track makes at each spot', 'Rotate through all 5 spots and note your weakest one'], ARRAY['Square your feet to the rim', 'Same distance every rep', 'Chart every spot'], ARRAY['Shooting from a different distance each rep', 'Drifting toward the rim to make it easier'], true),
  ('five-spot-threes', '5-Spot 3s', 'shooting', 'catch_and_shoot', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 12, '5 spots x 10 shots', 'Set up behind the arc at both corners, both wings, and the top of the key.', ARRAY['Start in a corner and take 10 catch-and-shoot threes, spinning the ball out to yourself', 'Keep your feet behind the line and land in the same spot you left from', 'Record makes out of 10 at each spot', 'Rotate to the next spot until you finish all 5'], ARRAY['Legs, not arms, for range', 'Toes behind the line', 'Same arc from every spot'], ARRAY['Letting your form break down to get the distance', 'Stepping on the line in the corners'], true),
  ('around-the-world', 'Around the World', 'shooting', 'competitive', 'beginner', 'solo', ARRAY['ball', 'hoop'], 10, 'Complete 7 spots and back', 'Mark 7 spots in an arc about 10 to 12 feet from the rim, from one baseline to the other.', ARRAY['Start at the first baseline spot and shoot until you make it', 'Each make moves you to the next spot', 'Work all the way around and back', 'Count total shots and try to beat that number next session'], ARRAY['Reset your feet at each spot', 'Pick your target early', 'Beat your last score'], ARRAY['Rushing shots to save time', 'Shooting before squaring up at the new spot'], true),
  ('beat-the-pro', 'Beat the Pro', 'shooting', 'competitive', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 10, 'Game to 11 points', 'Pick any shooting spot, such as the top of the key or a wing three.', ARRAY['Each make earns you 1 point', 'Each miss gives the imaginary pro 2 points', 'Play to 11 and record whether you won', 'Change spots each game or stay at a weak spot'], ARRAY['Every miss costs you', 'Stay in rhythm', 'Compete against your score'], ARRAY['Settling for low-effort shots when you fall behind', 'Rushing to catch up after a miss'], true),
  ('mikan-drill', 'Mikan Drill', 'shooting', 'close_range', 'beginner', 'solo', ARRAY['ball', 'hoop'], 5, '3 x 30 seconds', 'Stand under the rim on the right side of the lane with the ball held high.', ARRAY['Step with your left foot and make a right-hand layup off the backboard', 'Catch the ball out of the net without letting it touch the floor', 'Step with your right foot and make a left-hand layup on the other side', 'Keep alternating sides for 30 seconds, counting makes'], ARRAY['Ball stays high', 'Soft touch on the glass', 'Quick feet, quick hands'], ARRAY['Bringing the ball down to your waist between reps', 'Jumping off the wrong foot'], true),
  ('thirty-one', '31', 'shooting', 'competitive', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 12, 'Reach exactly 31 points', 'Use the whole half court: free throw line, midrange spots, and the three-point line.', ARRAY['Threes are worth 3, twos are worth 2, and free throws are worth 1', 'Choose your shots to reach exactly 31 points', 'If you go over 31, your score drops back to 21', 'Count total shots and try to finish in fewer next time'], ARRAY['Plan your finish', 'Every shot at game speed', 'Make the smart shot'], ARRAY['Taking lazy shots once you are close', 'Losing track of your score'], true),
  ('star-shooting-drill', 'Star Shooting Drill', 'shooting', 'movement', 'intermediate', 'solo', ARRAY['ball', 'hoop', 'cones'], 10, '3 rounds of 5 spots', 'Place cones at both corners, both wings, and the top of the key, plus one center cone at the free throw line.', ARRAY['Start at the center cone and speed dribble to a spot cone', 'Gather into a balanced stop and shoot', 'Grab your rebound and dribble back to touch the center cone', 'Go to the next spot and complete all 5 spots each round'], ARRAY['Sprint out, stop on balance', 'Shoulders square on arrival', 'Count makes every round'], ARRAY['Drifting on the shot because you did not stop your momentum', 'Walking between spots when tired'], true),
  ('one-dribble-pull-up', 'One-Dribble Pull-Up', 'shooting', 'off_the_dribble', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 10, '4 spots x 8 makes', 'Start at a wing or the top of the key about 18 feet out in triple threat.', ARRAY['Jab, then attack with one hard dribble going left or right', 'Pick up the ball on a hop or 1-2 stop, squaring to the rim', 'Rise straight up into your shot', 'Alternate directions every rep and track makes'], ARRAY['Hard dribble, soft shot', 'Stop on balance', 'Shoulders square on the rise'], ARRAY['Drifting forward and jumping into the rim', 'Dribbling too high and losing rhythm'], true),
  ('two-dribble-pull-up', 'Two-Dribble Pull-Up Series', 'shooting', 'off_the_dribble', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 12, '3 moves x 10 shots', 'Start at the top of the key, about 20 feet from the rim.', ARRAY['Attack with two dribbles toward the elbow and pull up', 'Next round, add a crossover on the second dribble before rising', 'Final round, add a between-the-legs on the second dribble', 'Track makes for each move and alternate elbows'], ARRAY['Last dribble hard and low', 'Shoot on the way up', 'Balance beats speed'], ARRAY['Picking up the ball too far out in front', 'Floating sideways on the jumper'], true),
  ('step-back-jumper', 'Step-Back Jumper', 'shooting', 'off_the_dribble', 'advanced', 'solo', ARRAY['ball', 'hoop'], 12, '4 spots x 8 shots', 'Start above the free throw line extended on a wing, about 18 to 20 feet from the rim.', ARRAY['Attack downhill with 1 or 2 hard dribbles', 'Plant your front foot and push back into space', 'Gather low with both feet landing in shooting position', 'Rise and shoot, then alternate directions each rep'], ARRAY['Sell the drive first', 'Push off the front foot', 'Land wide and balanced'], ARRAY['Fading away instead of rising straight up', 'Traveling by shuffling your feet on the landing'], true),
  ('side-step-three', 'Side-Step Three', 'shooting', 'off_the_dribble', 'advanced', 'solo', ARRAY['ball', 'hoop'], 12, '4 spots x 8 shots', 'Start one step inside the three-point line on either wing.', ARRAY['Take one hard dribble toward the middle to sell the drive', 'Step laterally behind the line with a quick side-step', 'Land balanced with feet set and square to the rim', 'Rise and shoot, alternating directions each rep'], ARRAY['Dribble hard, step wide', 'Land behind the line', 'Hips square before you rise'], ARRAY['Crossing your feet on the side-step and traveling', 'Landing on the line instead of behind it'], true),
  ('hesi-pull-up', 'Hesi Pull-Up', 'shooting', 'off_the_dribble', 'advanced', 'solo', ARRAY['ball', 'hoop', 'cones'], 12, '3 spots x 10 shots', 'Place a cone at the free throw line as a defender, and start at half court with the ball.', ARRAY['Push the ball at game speed toward the cone', 'Hit a hesitation 3 feet before the cone by raising your eyes and shoulders', 'Explode past it with one dribble and pull up for a jumper', 'Vary the shot spot between the elbows and the middle'], ARRAY['Slow to go fast', 'Eyes up on the hesi', 'Stop on a dime'], ARRAY['Stopping your feet completely on the hesitation', 'Pulling up while still moving forward'], true),
  ('chair-curl-jumpers', 'Chair Curl Jumpers', 'shooting', 'movement', 'intermediate', 'solo', ARRAY['ball', 'hoop', 'chair'], 10, '2 sides x 10 shots', 'Place a chair at the elbow as a screen and start on the block with the ball.', ARRAY['Take two steps into the paint to set up your cut, then sprint tight around the chair', 'As you come off the chair, toss the ball to the spot where you want to catch it', 'Catch with your inside foot down and rise into the shot', 'Track makes and switch to the other elbow'], ARRAY['Shoulder tight to the screen', 'Inside foot first', 'Square up before you rise'], ARRAY['Curling wide and giving the defender room to catch up', 'Shooting while your body is still turning'], true),
  ('drift-and-relocate', 'Drift and Relocate', 'shooting', 'relocation', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 10, '3 x 8 shots', 'Start at the wing with the ball and use the corner and the top of the key as relocation spots.', ARRAY['Toss the ball toward the corner so it bounces once', 'Drift to the corner behind the line while the ball is in the air', 'Catch with your feet already set and shoot', 'Alternate between drifting to the corner and lifting to the top of the key'], ARRAY['Move when the ball moves', 'Arrive ready to shoot', 'Space the floor'], ARRAY['Standing still and waiting for the ball', 'Arriving at the spot with your feet unset'], true),
  ('shot-fake-one-dribble', 'Shot Fake, One-Dribble Jumper', 'shooting', 'off_the_dribble', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 10, '5 spots x 6 shots', 'Start behind the three-point line at one of five spots with the ball in triple threat.', ARRAY['Sell a shot fake by bringing the ball to your shot pocket with your eyes on the rim', 'Keep your legs bent so you can explode', 'Take one long dribble past an imaginary closeout', 'Pull up for a midrange jumper and track makes'], ARRAY['Ball up, legs down', 'Eyes on the rim for the fake', 'One dribble, big step'], ARRAY['Standing straight up on the shot fake', 'Taking extra small dribbles instead of one long one'], true),
  ('partner-minute-shooting', 'Partner Minute Shooting', 'shooting', 'catch_and_shoot', 'intermediate', 'partner', ARRAY['ball', 'hoop'], 10, '5 rounds x 1 minute each', 'One shooter starts at a spot outside the paint, and the partner rebounds under the rim.', ARRAY['The shooter takes as many catch-and-shoot jumpers as possible in 1 minute', 'The rebounder passes crisply to the shooter''s shot pocket every time', 'The shooter moves to a new spot after every shot', 'Switch roles after each minute and compare makes'], ARRAY['Show your hands as the target', 'Move after every shot', 'Quality over speed'], ARRAY['Standing in one spot for the whole minute', 'Rushing shots and losing form'], true),
  ('transition-pull-ups', 'Transition Pull-Ups', 'shooting', 'game_speed', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 10, '10 reps each elbow', 'Start on the far baseline with the ball.', ARRAY['Speed dribble up the court at game speed', 'Gather into a 1-2 stop at the elbow', 'Rise into a pull-up jumper', 'Rebound, dribble back to the start, and alternate elbows'], ARRAY['Push the pace', 'Stop your momentum', 'Shoot up, not forward'], ARRAY['Slowing down well before the shot', 'Jumping forward and drifting into the lane'], true),
  ('elbow-to-elbow-shooting', 'Elbow-to-Elbow Shooting', 'shooting', 'movement', 'beginner', 'solo', ARRAY['ball', 'hoop'], 8, '3 x 1 minute', 'Start at the right elbow with the ball.', ARRAY['Shoot from the right elbow and chase your rebound', 'Dribble to the left elbow and square up', 'Shoot again and keep alternating elbows', 'Count makes in 1 minute and try to beat it next set'], ARRAY['Square up before you rise', 'Quick feet into the shot', 'Chase every rebound'], ARRAY['Shooting while your body is still turning', 'Walking between elbows'], true),
  ('hop-vs-one-two-shooting', 'Hop vs 1-2 Step Shooting', 'shooting', 'catch_and_shoot', 'beginner', 'solo', ARRAY['ball', 'hoop'], 10, '2 footwork styles x 15 shots', 'Start 15 feet from the rim on a wing with the ball.', ARRAY['Spin the ball out in front and catch on a two-foot hop, then shoot', 'Next, catch with a 1-2 step, landing inside foot first, then shoot', 'Take 15 shots with each footwork and track makes', 'Use the footwork that feels most balanced as your go-to'], ARRAY['Feet ready before the catch', 'Inside foot first on the 1-2', 'Land soft on the hop'], ARRAY['Catching with feet too narrow', 'Taking an extra shuffle step after the catch'], true),
  ('corner-three-series', 'Corner 3 Series', 'shooting', 'catch_and_shoot', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 10, '2 corners x 15 shots', 'Stand in the corner with both feet behind the three-point line.', ARRAY['Face half court, spin the ball out, and turn into your shot', 'Next set, start at the wing and drift to the corner on the catch', 'Last set, shot fake, take one side dribble along the line, and shoot', 'Record makes out of 15 in each corner'], ARRAY['Check your feet on the line', 'Turn into the shot', 'Same arc as every three'], ARRAY['Stepping out of bounds or on the line', 'Rushing because the corner shot feels close'], true),
  ('contested-partner-shooting', 'Contested Shooting', 'shooting', 'pressure', 'advanced', 'partner', ARRAY['ball', 'hoop'], 10, '5 spots x 6 shots', 'The shooter stands at a spot outside the arc, and the partner starts under the rim with the ball.', ARRAY['The partner passes to the shooter and sprints out with a high hand to contest', 'The contester stays under control and never makes contact with the shooter', 'The shooter catches and shoots over the high hand', 'Switch roles after each spot and track makes'], ARRAY['Eyes on the rim, not the hand', 'Same release under pressure', 'Contest high, no contact'], ARRAY['Changing your release to avoid the hand', 'Contesting by jumping into the shooter''s landing space'], true),
  ('knockout', 'Knockout', 'shooting', 'competitive', 'beginner', 'team', ARRAY['2 balls', 'hoop'], 10, 'Play 3 games', 'Players line up at the free throw line, with the first two players holding the balls.', ARRAY['The first player shoots from the free throw line', 'The second player shoots right away, trying to score before the player in front', 'After a miss, grab your rebound and score from anywhere as fast as possible', 'If the player behind you scores first, you are knocked out', 'The last player standing wins'], ARRAY['Stay calm after a miss', 'Quick putbacks', 'Hand off to the next player'], ARRAY['Rushing long shots from bad rebounds', 'Pushing or bumping other players while chasing rebounds'], true),
  ('hundred-makes-challenge', '100 Makes Challenge', 'shooting', 'catch_and_shoot', 'intermediate', 'solo', ARRAY['ball', 'hoop'], 20, '100 makes across 5 spots', 'Pick 5 spots at your best game range: both corners, both wings, and the top of the key.', ARRAY['Make 20 shots at each spot before moving on', 'Count total attempts so you can calculate your percentage', 'Take a short water break after each spot', 'Log your attempts and aim to lower them over time'], ARRAY['Every shot is a game shot', 'Track attempts, not just makes', 'Rest your legs, not your focus'], ARRAY['Shooting faster just to finish', 'Moving closer to the rim to boost the numbers'], true),
  ('sprint-back-threes', 'Sprint-Back Threes', 'shooting', 'game_speed', 'advanced', 'solo', ARRAY['ball', 'hoop'], 12, '4 x 1 minute', 'Start on the three-point line at the top of the key with the ball, using half court as your touch line.', ARRAY['Shoot a three from the top of the key and chase your rebound', 'Speed dribble to half court and touch the line with your foot', 'Turn and push back to a new spot on the arc, gather, and shoot', 'Keep going for 1 minute and count makes'], ARRAY['Sprint hard, stop hard', 'Legs under you', 'Same form when tired'], ARRAY['Shooting while still leaning forward from the sprint', 'Letting your arc drop as you tire'], true),
  ('game-winner-countdown', 'Game-Winner Countdown', 'shooting', 'pressure', 'advanced', 'solo', ARRAY['ball', 'hoop'], 10, '10 possessions', 'Start at half court with the ball and a phone timer, or count down out loud from 7.', ARRAY['Start a 7-second count and attack an imaginary defense', 'Use a move to create your shot before time runs out', 'Count a make only if the shot leaves your hand before zero', 'Alternate between pull-ups, step-backs, and drives each rep'], ARRAY['Know the clock', 'Get to your spot early', 'Shoot with confidence'], ARRAY['Settling for a rushed heave at the end', 'Using the same move every rep'], true),
  ('bank-shot-series', 'Bank Shot Series', 'shooting', 'close_range', 'beginner', 'solo', ARRAY['ball', 'hoop'], 8, '2 sides x 10 makes', 'Stand at a 45-degree angle to the backboard, about 8 to 12 feet from the rim.', ARRAY['Aim for the top corner of the square on the backboard', 'Shoot with soft touch so the ball kisses off the glass', 'Make 10 on the right side, then 10 on the left', 'Take a step back after every 5 makes if it feels easy'], ARRAY['Hit the top corner of the box', 'Soft touch on the glass', 'Use the angle'], ARRAY['Banking shots from straight on', 'Shooting too hard off the glass'], true),
  ('pound-dribble-series', 'Pound Dribble Series', 'ball_handling', 'stationary', 'beginner', 'solo', ARRAY['ball'], 6, '3 heights x 30 seconds each hand', 'Stand in an athletic stance in open space with the ball in one hand.', ARRAY['Pound the ball hard at knee height for 30 seconds', 'Switch to waist height, then ankle height, for 30 seconds each', 'Repeat all three heights with the other hand', 'Keep your eyes up and your off hand up to protect the ball'], ARRAY['Pound it, don''t pat it', 'Eyes up', 'Fingertips, not palm'], ARRAY['Standing straight up with locked knees', 'Staring at the ball the whole time'], false),
  ('ball-wraps', 'Ball Wraps', 'ball_handling', 'stationary', 'beginner', 'solo', ARRAY['ball'], 4, '3 x 20 wraps each direction', 'Stand in open space with feet shoulder-width apart and the ball in both hands.', ARRAY['Wrap the ball around your head 10 times, then reverse direction', 'Move down to wrap around your waist, then around both knees', 'Finish with figure-8 wraps through your legs', 'Speed up as you get comfortable without dropping the ball'], ARRAY['Fast hands', 'Use your fingertips', 'Stay low on the leg wraps'], ARRAY['Slapping the ball instead of controlling it', 'Standing straight up on the knee wraps'], false),
  ('figure-eight-dribble', 'Figure-8 Dribble', 'ball_handling', 'stationary', 'beginner', 'solo', ARRAY['ball'], 5, '3 x 30 seconds', 'Stand in a wide stance with feet a little more than shoulder-width apart.', ARRAY['Dribble the ball in a figure-8 pattern through and around your legs', 'Switch hands under your legs, keeping the ball low', 'Reverse direction after 15 seconds', 'Try to go faster each set without losing the ball'], ARRAY['Low and quick', 'Wide stance', 'Push the ball, don''t chase it'], ARRAY['Standing tall and bending only at the waist', 'Letting the ball bounce too high between the legs'], false),
  ('v-dribble', 'V-Dribble', 'ball_handling', 'stationary', 'beginner', 'solo', ARRAY['ball'], 5, '30 seconds front and side, each hand', 'Stand in an athletic stance with the ball in your right hand.', ARRAY['Push the ball side to side in front of you in a V shape with one hand', 'Roll your hand to the side of the ball to control it', 'Switch to a side V-dribble next to your hip, front to back', 'Repeat with the other hand'], ARRAY['Hand on the side of the ball', 'Keep the V tight', 'Eyes up'], ARRAY['Letting the V get too wide and losing control', 'Dribbling with a flat palm'], false),
  ('stationary-crossover', 'Stationary Crossover', 'ball_handling', 'stationary', 'beginner', 'solo', ARRAY['ball'], 5, '3 x 30 seconds', 'Stand in an athletic stance with your feet a little wider than your shoulders.', ARRAY['Dribble hard with your right hand, then cross the ball low to your left', 'Keep the crossover below your knees', 'Build speed while staying in control', 'Finish each set with 10 crosses as fast as possible'], ARRAY['Low and quick crosses', 'Snap it across', 'Stay in your stance'], ARRAY['Crossing the ball high at the waist', 'Standing up tall as you speed up'], false),
  ('weak-hand-stationary', 'Weak-Hand Stationary Series', 'ball_handling', 'weak_hand', 'beginner', 'solo', ARRAY['ball'], 8, '4 moves x 30 seconds', 'Stand in open space in an athletic stance with the ball in your weaker hand.', ARRAY['Pound dribble for 30 seconds using only your weak hand', 'Do 30 seconds of front V-dribbles, then side V-dribbles', 'Add 30 seconds of in-and-out dribbles', 'Finish with 30 seconds of dribbling while walking in a small circle'], ARRAY['Make the weak hand a strength', 'Fingertip control', 'Eyes up'], ARRAY['Switching to the strong hand when you lose control', 'Dribbling softly because the hand feels weak'], false),
  ('two-ball-pound', 'Two-Ball Pound', 'ball_handling', 'two_ball', 'beginner', 'solo', ARRAY['2 balls'], 5, '3 x 30 seconds each pattern', 'Stand in an athletic stance with a ball in each hand.', ARRAY['Pound both balls at the same time at waist height', 'Switch to alternating dribbles, one up while the other is down', 'Lower both balls to knee height for the final set', 'Rest 20 seconds between sets'], ARRAY['Both hands work equally', 'Stay low', 'Rhythm first, then speed'], ARRAY['Letting the weak-hand ball die out', 'Looking down at only one ball'], false),
  ('cone-weave-dribble', 'Cone Weave Dribble', 'ball_handling', 'on_the_move', 'beginner', 'solo', ARRAY['ball', 'cones'], 8, '4 trips up and back', 'Set 6 cones in a straight line about 6 feet apart, starting at the baseline.', ARRAY['Dribble through the cones in a zig-zag using the hand away from the cone', 'Switch hands with a crossover at each cone', 'Start at a walking pace, then jog, then go at game speed', 'Speed dribble back to the start along the outside of the cones'], ARRAY['Ball away from the cone', 'Cross low at each cone', 'Eyes up by the last cone'], ARRAY['Using the same hand the whole time', 'Going so fast you knock over the cones'], false),
